SELECT wdp.approve_status AS status, wdpd.qty AS qty, wdp.create_time AS estimateSalesDate, wdp.id AS sourceId, wdp.code AS sourceCode FROM #{tableName} AS wdp INNER JOIN #{tableDetailName} AS wdpd ON wdpd.is_deleted = FALSE AND wdpd.main_id = wdp.id WHERE wdp.is_deleted = FALSE AND wdp."type" = #{type} AND wdp.shop_id = #{result.replenishment.shopId} AND wdpd.sku_id = #{result.replenishment.skuId}
AND ( (wdp.status = 'approve' AND wdp.delivery_status = 'unShipped')
OR wdp.status IN
#{code}
)
AND wdp.status IN
#{code}

select sum(#{code})
from #{tableName}
where is_deleted = false
  and sku_id = #{result.replenishment.skuId}
  and warehouse_id = #{result.replenishment.fbaWarehouseId}

SELECT warehouse_id AS warehouseId, SUM ( qty ) AS qty FROM #{tableName} WHERE is_deleted = false AND dict_inventory_status IN
#{code}
AND sku_id = #{skuId} GROUP BY warehouse_id

